import { ChoicePoll } from "@/components/ui/choice-poll"

const options = [
  { value: "react", label: "React" },
  { value: "vue", label: "Vue" },
  { value: "angular", label: "Angular" },
  { value: "svelte", label: "Svelte" },
]

const initialVotes = { react: 245, vue: 178, angular: 92, svelte: 134 }

export default function Demo() {
  const [votes, setVotes] = useState<Record<string, number>>(initialVotes)
  const [hasVoted, setHasVoted] = useState(false)

  return (
    <div className="w-full max-w-md p-6">
      <ChoicePoll.Root
        votes={votes}
        hasVoted={hasVoted}
        showResults
        onValueChange={(value) => {
          if (hasVoted) return
          const choice = Array.isArray(value) ? value[0] : value
          if (!choice) return
          setVotes((v) => ({ ...v, [choice]: (v[choice] ?? 0) + 1 }))
          setHasVoted(true)
        }}
      >
        <ChoicePoll.Header>
          <ChoicePoll.Title>What is your favorite frontend framework?</ChoicePoll.Title>
          <ChoicePoll.Description>
            Vote for the framework you enjoy working with the most.
          </ChoicePoll.Description>
        </ChoicePoll.Header>
        <ChoicePoll.Options>
          {options.map((o) => (
            <ChoicePoll.Option key={o.value} value={o.value}>
              <ChoicePoll.Indicator />
              <ChoicePoll.Label>{o.label}</ChoicePoll.Label>
              <ChoicePoll.Percentage />
            </ChoicePoll.Option>
          ))}
        </ChoicePoll.Options>
        <ChoicePoll.Footer />
      </ChoicePoll.Root>
    </div>
  )
}

"use client"

import { useState } from "react"

import {
  PollWidget,
  PollWidgetContent,
  PollWidgetOptions,
  PollWidgetOption,
  PollWidgetQuestion,
  PollWidgetResults,
  PollWidgetSubmit,
} from "@/components/ui/poll-widget"

const OPTIONS = [
  { id: "speed", label: "Faster build times" },
  { id: "dx", label: "Better DX tooling" },
  { id: "ai", label: "AI-assisted coding" },
  { id: "collab", label: "Team collaboration" },
]

const BASE_VOTES: Record<string, number> = {
  speed: 312,
  dx: 241,
  ai: 198,
  collab: 155,
}

export default function Demo() {
  const [votes, setVotes] = useState(BASE_VOTES)
  const [hasVoted, setHasVoted] = useState(false)

  function handleVote(selected: string[]) {
    setVotes((prev) => {
      const next = { ...prev }
      for (const id of selected) {
        next[id] = (next[id] ?? 0) + 1
      }
      return next
    })
    setHasVoted(true)
  }

  return (
    <div className="w-full max-w-md p-6">
      <PollWidget
        question="What would improve your workflow the most?"
        description="Pick the improvement you care about most."
        options={OPTIONS}
        votes={votes}
        hasVoted={hasVoted}
        onVote={handleVote}
        mode="inline"
        autoCollapseDelay={0}
      >
        <PollWidgetContent>
          <PollWidgetQuestion />
          <PollWidgetOptions>
            {OPTIONS.map((opt) => (
              <PollWidgetOption key={opt.id} value={opt.id} />
            ))}
          </PollWidgetOptions>
          <PollWidgetResults />
          <PollWidgetSubmit />
        </PollWidgetContent>
      </PollWidget>
    </div>
  )
}

