  const status = CYCLE[step];

  return (
    <div className="flex min-h-[460px] w-full items-center justify-center bg-background p-8">
      <div className="flex min-w-[460px] flex-col items-start gap-4 text-foreground">
        <p className="mb-1 text-xl text-muted-foreground">Running checks on the release branch…</p>
        <CallChip icon="search" name="grep" argument={'"TODO" src/'} status="done" size={48} />
        <CallChip icon="file" name="read" argument="src/app/checkout.tsx" status="done" size={48} />
        <CallChip icon="terminal" name="bash" argument="npm run test -- --ci" status={status} expectedMs={1800} size={48} showTimer />
        <CallChip icon="edit" name="edit" argument="src/lib/cart.ts" status={status === "done" ? "running" : "idle"} size={48} />
      </div>
    </div>
  );
}

