              <GaugeValueText className="text-2xl font-semibold tabular-nums" />
              <GaugeLabel className="sr-only">{m.label}</GaugeLabel>
            </Gauge>
            <span className="text-sm font-medium text-muted-foreground">
              {m.label}
            </span>
          </div>
        );
      })}
